import type { OverlayTemplate } from '../../../component/Overlay'

import { withPerfPipeline } from '../../interaction/perf'

import { ELLIOTT_TRIANGLE_LABELS, elliottWaveFigures } from './elliottCommon'
import { TV_TAN_ORANGE } from './patternCommon'
import type { PatternExtendData } from './patternCommon'

/**
 * 'elliottTriangle' — TradingView "Elliott triangle wave (ABCDE)" —
 * 6 points. Zigzag polyline with alternating (0)·(A)·(B)·(C)·(D)·(E)
 * labels at the default Intermediate degree.
 */
const elliottTriangle: OverlayTemplate<PatternExtendData> = {
  name: 'elliottTriangle',
  totalStep: 7,
  needDefaultPointFigure: false,
  needDefaultXAxisFigure: false,
  needDefaultYAxisFigure: false,

  createPointFigures: withPerfPipeline(params =>
    elliottWaveFigures(ELLIOTT_TRIANGLE_LABELS, params, TV_TAN_ORANGE)
  )
}

export default elliottTriangle
