import type { OverlayTemplate } from '../../../component/Overlay'

import type { PitchforkExtendData } from './pitchforkCommon'
import { createPitchforkTemplate } from './pitchforkCommon'

/**
 * 'insidePitchfork' — Inside Pitchfork: the median ray starts at p1 and
 * passes through the midpoint of the p2→p3 leg (the fork lives "inside"
 * the p2-p3 span rather than hinging on the p1→p2 segment).
 */
const insidePitchfork: OverlayTemplate<PitchforkExtendData> = createPitchforkTemplate('insidePitchfork', 'inside')

export default insidePitchfork
