import type { OverlayTemplate } from '../../../component/Overlay'

import type { PitchforkExtendData } from './pitchforkCommon'
import { createPitchforkTemplate } from './pitchforkCommon'

/**
 * 'pitchfork' — the original Andrews' Pitchfork: median ray through the
 * p1→p2-midpoint pivot, channel bounds parallel to the median at offsets
 * determined by the level coefficients. Three anchors.
 */
const pitchfork: OverlayTemplate<PitchforkExtendData> = createPitchforkTemplate('pitchfork', 'original')

export default pitchfork
